import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, w;
        Edge(int to, int w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node {
        int id;
        long dist;
        Node(int id, long dist) {
            this.id = id;
            this.dist = dist;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int E = Integer.parseInt(st.nextToken());
        int R = Integer.parseInt(st.nextToken());

        ArrayList<Edge>[] adj = new ArrayList[E + 1];
        for (int i = 1; i <= E; i++) {
            adj[i] = new ArrayList<>();
        }

        int[] U = new int[R];
        int[] V = new int[R];
        int[] W = new int[R];

        for (int i = 0; i < R; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            U[i] = a;
            V[i] = b;
            W[i] = c;
            adj[a].add(new Edge(b, c));
            adj[b].add(new Edge(a, c));
        }

        int[] parent = new int[E + 1];
        int[] depth = new int[E + 1];
        long[] distRoot = new long[E + 1];
        boolean[] visited = new boolean[E + 1];

        for (int r = 1; r <= E; r++) {
            if (!visited[r]) {
                visited[r] = true;
                parent[r] = 0;
                depth[r] = 0;
                distRoot[r] = 0;

                ArrayDeque<Integer> stack = new ArrayDeque<>();
                ArrayDeque<Integer> iterStack = new ArrayDeque<>();
                stack.push(r);
                iterStack.push(0);

                while (!stack.isEmpty()) {
                    int u = stack.peek();
                    int idx = iterStack.pop();

                    if (idx < adj[u].size()) {
                        iterStack.push(idx + 1);
                        Edge e = adj[u].get(idx);
                        int v = e.to;

                        if (!visited[v]) {
                            visited[v] = true;
                            parent[v] = u;
                            depth[v] = depth[u] + 1;
                            distRoot[v] = distRoot[u] + e.w;
                            stack.push(v);
                            iterStack.push(0);
                        }
                    } else {
                        stack.pop();
                    }
                }
            }
        }

        int[] cycleId = new int[E + 1];
        Arrays.fill(cycleId, -1);
        ArrayList<Long> cyclesLen = new ArrayList<>();

        for (int i = 0; i < R; i++) {
            int a = U[i], b = V[i], w = W[i];
            if (parent[a] == b || parent[b] == a) continue;

            int x, y;
            if (depth[a] > depth[b]) {
                x = a;
                y = b;
            } else {
                x = b;
                y = a;
            }

            if (depth[x] < depth[y]) {
                int tmp = x;
                x = y;
                y = tmp;
            }

            long len = distRoot[x] - distRoot[y] + w;
            int cid = cyclesLen.size();

            int cur = x;
            while (cur != y) {
                cycleId[cur] = cid;
                cur = parent[cur];
            }
            cycleId[y] = cid;
            cyclesLen.add(len);
        }

        st = new StringTokenizer(br.readLine());
        int K = Integer.parseInt(st.nextToken());
        PrintWriter out = new PrintWriter(System.out);
        long INF = Long.MAX_VALUE / 4;

        for (int q = 0; q < K; q++) {
            st = new StringTokenizer(br.readLine());
            int X = Integer.parseInt(st.nextToken());
            int T = Integer.parseInt(st.nextToken());

            long[] dist = new long[E + 1];
            Arrays.fill(dist, INF);
            dist[X] = 0;

            PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(n -> n.dist));
            pq.add(new Node(X, 0));

            while (!pq.isEmpty()) {
                Node curNode = pq.poll();
                int u = curNode.id;
                long d = curNode.dist;

                if (d != dist[u]) continue;

                for (Edge e : adj[u]) {
                    int v = e.to;
                    long nd = d + e.w;
                    if (nd < dist[v]) {
                        dist[v] = nd;
                        pq.add(new Node(v, nd));
                    }
                }
            }

            long[] minDist = new long[cyclesLen.size()];
            Arrays.fill(minDist, INF);

            for (int v = 1; v <= E; v++) {
                int cid = cycleId[v];
                if (cid != -1 && dist[v] < minDist[cid]) {
                    minDist[cid] = dist[v];
                }
            }

            long ans = INF;
            for (int i = 0; i < cyclesLen.size(); i++) {
                long L = cyclesLen.get(i);
                if (L >= T && minDist[i] != INF) {
                    long cost = L + 2 * minDist[i];
                    if (cost < ans) ans = cost;
                }
            }

            if (ans == INF) {
                out.println(-1);
            } else {
                out.println(ans);
            }
        }

        out.flush();
    }
}
